namespace RestaurantCopilot.Infrastructure.Persistence.Seeding;

// Shapes of the JSON files in /seed (generated by seed/generate.cs).

internal sealed record RestaurantSeed(string Name, string Cuisine, string City, string TimeZoneId);

internal sealed record MenuItemSeed(string Key, string Name, string Description, string Category, decimal Price);

internal sealed record OrderSeed(
    int Number,
    DateTimeOffset PlacedAt,
    string Channel,
    string Status,
    IReadOnlyList<OrderItemSeed> Items);

internal sealed record OrderItemSeed(string MenuItem, int Quantity);

internal sealed record ReviewSeed(int OrderNumber, string? MenuItem, int Rating, string Comment, DateTimeOffset CreatedAt);
